function checkedImage(bytes, mediaType) {
  const mimeType =
    typeof mediaType === "string" ? mediaType.split(";")[0].trim().toLowerCase() : "";
  if (!bytes || bytes.length < 12 || bytes.length > 2 * 1024 * 1024)
    throw new Error("Image must be at most 2 MiB");
  const ascii = (index, length) => String.fromCharCode(...bytes.subarray(index, index + length));
  if (
    mimeType === "image/png" &&
    bytes.length >= 57 &&
    [137, 80, 78, 71, 13, 10, 26, 10].every((octet, i) => bytes[i] === octet) &&
    ascii(12, 4) === "IHDR"
  ) {
    const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.length);
    if (view.getUint32(8) === 13 && view.getUint32(16) && view.getUint32(20)) {
      let offset = 33;
      let imageData = false;
      while (offset + 12 <= bytes.length) {
        const length = view.getUint32(offset);
        const type = ascii(offset + 4, 4);
        const end = offset + 12 + length;
        if (end > bytes.length) break;
        if (type === "IDAT" && length > 0) imageData = true;
        if (type === "IEND" && length === 0 && imageData && end === bytes.length) return mimeType;
        offset = end;
      }
    }
  }
  if (
    mimeType === "image/jpeg" &&
    bytes[0] === 0xff &&
    bytes[1] === 0xd8 &&
    bytes[bytes.length - 2] === 0xff &&
    bytes[bytes.length - 1] === 0xd9
  ) {
    let offset = 2;
    let frame = false;
    while (offset + 4 < bytes.length && bytes[offset] === 0xff) {
      while (bytes[offset] === 0xff) offset++;
      const marker = bytes[offset++];
      const length = bytes[offset] * 256 + bytes[offset + 1];
      if (length < 2 || offset + length >= bytes.length - 2) break;
      if (marker >= 0xc0 && marker <= 0xcf && ![0xc4, 0xc8, 0xcc].includes(marker))
        frame = length >= 8;
      if (marker === 0xda && frame && length >= 6) return mimeType;
      offset += length;
    }
  }
  throw new Error("Image bytes do not match a complete PNG or JPEG response");
}

function stockImageInput(body, bucket, checkImage) {
  if (!body || typeof body !== "object" || Array.isArray(body))
    throw new Error("Send a JSON object with one image field");
  const fields = ["imageUrl", "image_url", "image", "imageBase64"].filter((key) =>
    Object.hasOwn(body, key),
  );
  if (fields.length !== 1 || typeof body[fields[0]] !== "string" || !body[fields[0]].trim()) {
    throw new Error("Send one imageUrl, image_url, image, or imageBase64 field");
  }
  const field = fields[0];
  const input = body[field].trim();
  if (field !== "imageBase64" && !input.startsWith("data:")) {
    const url =
      input.length <= 4096 &&
      /^https:\/\/storage\.googleapis\.com\/([a-z0-9._-]+)\/([^?\s#\\]+)(?:\?[^\s#\\]*)?$/.exec(
        input,
      );
    if (
      bucket === "YOUR_GCS_BUCKET" ||
      !url ||
      url[1] !== bucket ||
      url[2].split("/").some((segment) => {
        const decoded = decodeURIComponent(segment);
        return (
          !decoded || decoded === "." || decoded === ".." || /[\/\\%\x00-\x1f\x7f]/.test(decoded)
        );
      })
    )
      throw new Error(
        "Use a direct HTTPS object URL in your configured Google Cloud Storage bucket",
      );
    return { sourceUrl: input, remote: true };
  }

  const tagged = /^data:(image\/(?:jpeg|png));base64,([A-Za-z0-9+/]+=*)$/.exec(input);
  if (!tagged && input.startsWith("data:")) throw new Error("Use a PNG or JPEG image data URL");
  const encoded = tagged?.[2] ?? input;
  if (
    encoded.length > Math.ceil((2 * 1024 * 1024) / 3) * 4 ||
    !/^[A-Za-z0-9+/]+={0,2}$/.test(encoded)
  ) {
    throw new Error("Use valid base64 for a PNG or JPEG image up to 2 MiB");
  }
  const bytes = Buffer.from(encoded, "base64");
  const canonical = bytes.toString("base64");
  if (encoded !== canonical && encoded !== canonical.replace(/=+$/, ""))
    throw new Error("Use canonical image base64");
  const mime = tagged?.[1] ?? (bytes[0] === 0x89 && bytes[1] === 0x50 ? "image/png" : "image/jpeg");
  return { remote: false, dataUrl: "data:" + checkImage(bytes, mime) + ";base64," + canonical };
}

const bucket = "YOUR_GCS_BUCKET";
const item = $input.first().json;
try {
  if (!/^application\/json(?:;|$)/i.test(item.headers?.["content-type"] ?? ""))
    throw new Error("Use Content-Type application/json");
  return [{ json: { valid: true, ...stockImageInput(item.body, bucket, checkedImage) } }];
} catch (error) {
  return [{ json: { valid: false, error: error.message } }];
}

