const request = $("Validate the image and configure the bucket").first().json;
let imageUrl = request.dataUrl;
if (request.remote) {
  const item = $input.first();
  if (item.json.statusCode !== 200 || !item.binary?.data)
    throw new Error("The approved image download must return HTTP 200");
  const bytes = await helpers.getBinaryDataBuffer(0, "data");
  const mediaType = checkedImage(
    bytes,
    item.json.headers?.["content-type"] ?? item.binary.data.mimeType,
  );
  imageUrl = "data:" + mediaType + ";base64," + bytes.toString("base64");
}
return [
  {
    json: {
      input: [
        { role: "user", content: [{ type: "input_image", image_url: imageUrl, detail: "high" }] },
      ],
    },
  },
];

function stockMetadata(reply) {
  if (reply?.status !== "completed" || !Array.isArray(reply.output))
    throw new Error("OpenAI did not complete image analysis");
  const messages = reply.output.filter((item) => item?.type === "message");
  const message = messages[0];
  if (
    messages.length !== 1 ||
    message.role !== "assistant" ||
    message.status !== "completed" ||
    !Array.isArray(message.content) ||
    message.content.length !== 1 ||
    message.content[0]?.type !== "output_text"
  ) {
    throw new Error("OpenAI did not return structured image metadata");
  }
  const data = JSON.parse(message.content[0].text);
  const clean = (text, limit) => {
    if (
      typeof text !== "string" ||
      !text.trim() ||
      text.length > limit ||
      /[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]/.test(text)
    )
      throw new Error("OpenAI returned invalid image metadata");
    return text.trim();
  };
  const title = clean(data?.title, 160);
  const description = clean(data?.description, 1200);
  if (
    title.split(/\s+/u).length >= 12 ||
    !Array.isArray(data.keywords) ||
    data.keywords.length > 40
  ) {
    throw new Error("OpenAI returned an invalid stock title or keyword list");
  }
  const keywords = [
    ...new Set(
      data.keywords.map((term) => {
        const keyword = clean(term, 70).toLowerCase();
        if (/[;\t\r\n]/.test(keyword))
          throw new Error("OpenAI returned a keyword with a separator");
        return keyword;
      }),
    ),
  ];
  if (keywords.length < 20) throw new Error("OpenAI did not return 20 distinct keywords");

  const csvCell = (text) => {
    const formula = /^[\p{White_Space}\p{Cf}]*[=+\-@＝＋－＠]/u.test(text);
    const safe = formula ? "'" + text : text;
    return '"' + safe.replaceAll('"', '""') + '"';
  };
  const csv_row = [title, description, keywords.join("; ")].map(csvCell).join(",");
  return {
    title,
    description,
    keywords,
    keyword_count: keywords.length,
    csv_row,
    csv: '"title","description","keywords"\n' + csv_row,
  };
}

return [{ json: stockMetadata($input.first().json) }];
